nodes.statement:
Recall the unattenuated Euclidean X-ray transform of an unknown function $f \in L^{2}(\Omega)$ supported on some bounded domain $\Omega$, which is given by
\begin{equation*}
Xf(x,\theta) = \int_{\mathbb{R}}f(x+t\theta)\,dt, \quad (x,\theta) \in \Omega \times \mathbb{S}^{n-1}.
\end{equation*}

In short, they consider the problem of recovering an unknown potential $q \in L^{\infty}(\Omega)$ given the partial Cauchy data set
\begin{align*}
\mathcal{C}_{q}^{\Gamma_{D}, \Gamma_{N}} & = \{ (u \vert_{\Gamma_{D}}, \partial_{\nu}u \vert_{\Gamma_{N}}) \, | \, (-\Delta + q)u = 0 \mathrm{ in }\Omega,\, u \in H_{\Delta}(\Omega),\\
& \qquad \qquad \qquad \qquad \quad \mathrm{supp}(u \vert_{\partial \Omega}) \subset \Gamma_{D} \}.
\end{align*}

The authors of \cite{salokenig} then prove the following: let $\Gamma_{i} \subset \partial M_{\mathrm{tan}}$ such that there exists a nonempty open subset $E$ of $\partial M_{0}$, and suppose $\Gamma_{D} = \Gamma_{N} = \Gamma$ for some neighborhood $\Gamma$ in $\partial M$ of the set $\overline{\partial M_{+} \cup \partial M_{-} \cup \Gamma_{a}}$ for $\Gamma_{a} = \partial M_{\mathrm{tan}} \setminus \Gamma_{i}$. If $q_{1},q_{2}$ are two potentials such that $\mathcal{C}_{g,q_{1}}^{\Gamma_{D},\Gamma_{N}} = \mathcal{C}_{g,q_{2}}^{\Gamma_{D},\Gamma_{N}}$, then
\begin{equation*}
\int_{0}^{L}e^{-2\lambda t}( c(q_{1} - q_{2})\,{\hat{}}\,(2\lambda, \gamma(t))\,dt = 0
\end{equation*}
for all nontangential broken rays $\gamma: [0,L] \to M_{0}$ with endpoints in $E$ and for any $\lambda \in \mathbb{R}$. Here $( \cdot )\,{\hat{}}$ denotes the Fourier transform with respect to $x_{1}$.

conclusions:
\int_{0}^{L}e^{-2\lambda t}( c(q_{1} - q_{2})\,{\hat{}}\,(2\lambda, \gamma(t))\,dt = 0
\end{equation*}
for all nontangential broken rays $\gamma: [0,L] \to M_{0}$ with endpoints in $E$ and for any $\lambda \in \mathbb{R}$

nodes.statement:
We also define, for a general open subset $E \subset \partial \Omega$, the set
\begin{equation}
\Gamma_{\pm}(E) := \{(x,\theta) \in S\Omega \, | \, x \in E, \pm \theta \cdot \nu(x) > 0\}.
\end{equation}

We will call any unit speed curve $\gamma_{x,\theta}$ a \textit{regular broken ray} in $\Omega$ if
\begin{enumerate}
\item[(a)] its associated tangent vector field $(\gamma_{x,\theta}(t), \dot{\gamma}_{x,\theta}(t))$ intersects $\Gamma_{-}(E)$\\
\item[(b)] it consists of finitely many straight line segments $\gamma_{x,\theta,1}, \gamma_{x,\theta,2}, \ldots, \gamma_{x,\theta,N}$ before hitting $E$ again\\
\item[(c)] it does not intersect $\partial E$, and\\
\item[(d)] it obeys the geometrical optics reflection law 
\begin{equation}
\dot{\gamma}_{x,\theta,j+1}(0) = \dot{\gamma}_{x,\theta,j}(L_{j}) - 2\left\langle \nu(\gamma_{x,\theta,j}(L_{j})),\dot{\gamma}_{x,\theta,j}(L_{j}) \right\rangle \nu(\gamma_{x,\theta,j}(L_{j})), \,1 \leq j \leq N.
\end{equation}
\end{enumerate}
Here $L_{j}$ denotes the length of $\gamma_{x,\theta,j}$ and the subscripts refer to the fact that $(\gamma_{x,\theta}(0), \dot{\gamma}_{x,\theta}(0)) = (x,\theta)$.

The operator $I_{0,E}:L^{2}(\Omega) \to L^{2}(\Gamma_{-}, d\Sigma)$, where $d\Sigma = |\nu(x) \cdot \theta|\, dS(x)\, d\theta$ is the standard measure on $\Gamma_{-}$, is defined by
\begin{equation}
I_{0, E}f(\gamma_{x,\theta}) = I_{0, E}f(x,\theta) := \sum_{j=0}^{N(x,\theta)}\int_{\rn{+}} f(\pi_{1} \circ T^{j}(x,\theta) + t \pi_{2}\circ T^{j}(x,\theta))\,dt. \end{equation}
for all regular broken rays $\gamma_{x,\theta}$.

Here 
\begin{equation}
(z_{j}(x,\theta),\theta_{j}(x,\theta)) = T^{j}(x+\tau_{-}(x,\theta)\theta,\theta), \quad (x,\theta) \in S\Omega. \end{equation}

Given a reflection signature $(l_{1},l_{2})$, we can compute the reflected version of a point $w \in \Omega$ by
\begin{align}
\widetilde{w} = R_{l_{1},l_{2}}(w) & = \left( l_{1} + \frac{1 - (-1)^{l_{1}}}{2} + (-1)^{l_{1}}w_{1}, l_{2} + \frac{1 - (-1)^{l_{2}}}{2} + (-1)^{l_{2}}w_{2} \right)\\
w = R_{l_{1},l_{2}}^{-1}(\widetilde{w}) & = \left( (-1)^{l_{1}+1}l_{1} + \frac{1-(-1)^{l_{1}}}{2} + (-1)^{l_{1}}\widetilde{w}_{1}, \, (-1)^{l_{2}+1}l_{2} + \frac{1-(-1)^{l_{2}}}{2} + (-1)^{l_{2}}\widetilde{w}_{2} \right).
\end{align}

Similarly, given an angle $\theta$, $S_{l_{1},l_{2}}(\theta)$ is the angle after an $(l_{1},l_{2})$ reflection. 
\begin{align}
\eta = S_{l_{1},l_{2}}(\theta) &= (-1)^{l_{1}+l_{2}}\theta + \frac{\pi}{2}\left[ 1 - (-1)^{l_{1}} \right]\\
\theta = S_{l_{1},l_{2}}^{-1}(\eta) & = (-1)^{l_{2}}\left( (-1)^{l_{1}} \eta + \frac{1-(-1)^{l_{1}}}{2}\pi \right).
\end{align}

For a given $N_{max} \in \mathbb{N}$, we define the \textit{visible set} by
\begin{align}
\mathcal{M} & := \{x \in \Omega \, | \, \forall \xi \in \mathbb{S}^{1}, (x,\xi) \in N^{*}\gamma \textrm{ for some regular broken ray $\gamma$}\\
& \hspace{7cm} \textrm{ with $N(\gamma) \leq N_{max}$}\}. \notag
\end{align}

The weight functions $w_{j}$ on $S\Omega$ are given by
\begin{align}
w_{j}(y,\eta) & = \exp\left( -\sum_{m=0}^{j-1} \int_{\mathbb{R}_{+}}\sigma( z_{m-j}+\tau \theta_{m-j},\theta_{m-j})\,d\tau\right) \exp\left( -\int_{\mathbb{R}_{+}}\sigma(y - \tau \eta, \eta)\,d\tau \right)\notag\\
& = \exp\left( -\sum_{m=1}^{j} \int_{\mathbb{R}_{+}}\sigma( z_{-m}+\tau \theta_{-m},\theta_{-m})\,d\tau\right) \exp\left( -\int_{\mathbb{R}_{+}}\sigma(y - \tau \eta, \eta)\,d\tau \right)\notag
\end{align}

First we define an extension of $\sigma$ on $\widetilde{\Omega}\times \mathbb{S}^{1}$ by
\begin{equation}
\widetilde{\sigma}(x,\theta) = \left\{ \begin{array}{ll}
\sigma( R_{l_{1},l_{2}}^{-1}(x), S_{l_{1},l_{2}}^{-1}(\theta)) & \textrm{ for }x \in [l_{1},l_{1}+1] \times [l_{2},l_{2}+1],\\
&  \quad (l_{1},l_{2}) \in \mathbb{Z}^{2}.
\end{array}\right.
\end{equation}

First we recall an identity from \cite{inversesource} which asserts that for any function $f \in L^{2}(\Omega, \mathbb{S}^{n-1})$, we have
\begin{equation*}
\int_{\Gamma_{-}}\int_{\mathbb{R}_{+}} f(x+t\theta, \theta)\,dt\,d\Sigma = \int_{\Omega \times \mathbb{S}^{n-1}} f(x,\theta)\,dx\,d\theta.
\end{equation*}

Let $\alpha = \sum_{k=1}^{N_{\alpha}}\alpha_{k}$ be a sum of smooth cutoff functions on $\Gamma_{-}(E)$ in the sense of the previous paragraph, and consider the regularized operator
\begin{equation}
I_{\sigma,E,\alpha} := \sum_{k=1}^{N_{\alpha}}\alpha_{k} I_{\sigma,E}.
\end{equation}

Then
\begin{equation}
N_{\sigma, E, \alpha} := I_{\sigma, E,\alpha}^{*} I_{\sigma, E, \alpha} =  \sum_{k_{1}=1,k_{2}=1}^{N_{\alpha}}I_{\sigma,E}^{*}\alpha_{k_{1}}\alpha_{k_{2}}I_{\sigma, E}.
\end{equation}
The transpose is taken with respect to the standard measure $|\nu(x) \cdot \theta|\,dS(x)\,d\theta$ on $\Gamma_{-}(E)$.

We also define the \textit{microlocally visible set} by
\begin{equation}
\mathcal{M}' := \{ (z,\xi) \in T^{*}\Omega \, | \, (z,\xi) \in N^{*}\gamma_{x,\theta} \textrm{ for some }(x,\theta) \textrm{ with }\alpha(x,\theta) > 0\}.
\end{equation}

\begin{enumerate}
\item[(a)] Fix $\sigma$ that is $0$ in a neighborhood of $\partial \Omega$, and choose $\alpha \in C^{\infty}(\Gamma_{-})$ as above with reflection threshold $N_{max}$. Fix a set $K \Subset \mathcal{M}$ compactly contained in the visible set $\mathcal{M}$. If $I_{\sigma, E, \alpha}$ is injective on $L^{2}(K)$, then
\begin{equation}
\frac{1}{C}\|f\|_{L^{2}(K)} \leq \|N_{\sigma, E, \alpha}f \|_{H^{1}(\Omega)} \leq C\|f\|_{L^{2}(K)}. \end{equation}
\item[(b)] Let $\alpha^{0}$ be as above related to some fixed $\sigma_{0}$. Assume that $I_{\sigma_{0}, E, \alpha^{0}}$ is injective on $L^{2}(K)$. Then estimate (\ref{eq:stabilityestimate}) remains true for $(\sigma, \alpha)$ in a small $C^{2}$ neighborhood of $(\sigma_{0}, \alpha^{0})$ such that $\sigma \equiv 0$ near $\partial \Omega$, and with a uniform constant $C > 0$.
\end{enumerate}

$N_{\sigma,E,\alpha} = N_{\sigma,E,\alpha,ballistic} + N_{\sigma,E,\alpha,reflect}$ where $N_{\sigma,E,\alpha,ballistic}$ is a classical pseudo differential operator of order $-1$, elliptic on $\mathcal{M}$, and $N_{\sigma, E,\alpha,reflect}$ is an operator with $C_{0}^{\infty}(\Omega \times \Omega)$ Schwartz kernel. Thus there exists a classical pseudo differential operator $Q$ in $\Omega$ of order $1$ such that
\begin{equation}
QN_{\sigma, E,\alpha}f = f + QN_{\sigma,E,\alpha,reflect}f + S_{1}
\end{equation}
for any $f \in \mathcal{D}'(K)$, where $S_{1}$ is an operator with $C_{0}^{\infty}(\Omega \times \Omega)$ Schwartz kernel.

conclusions:
there exists a classical pseudo differential operator $Q$ in $\Omega$ of order $1$ such that
\begin{equation}
QN_{\sigma, E,\alpha}f = f + QN_{\sigma,E,\alpha,reflect}f + S_{1}
\end{equation}

